    excerpt: '沃尔玛刚发布了第一份真正意义上的 AI 购物智能体规则书，Agent Profiles 和消费上限 11 月上线。以下是对 Shopify 商家的实际含义，以及现在就该做的三件数据事。',
    quickAnswer: '2026 年 10 月 21 日，沃尔玛针对 AI 购物智能体宣布了三件事：Walmart Agent Gateway，一个面向公司和开发者的 beta 版 MCP 服务器；Agent Profiles，11 月上线，让消费者要求每笔购买都需批准或设一个消费上限；以及一套针对 AI 智能体的条款，已经生效。智能体能搜索库存并购买，但它们永远拿不到支付卡数据，购买默认需要消费者批准。亚马逊走了相反的路，把 Meta 的 Muse 这类智能体封掉了。对 Shopify 商家来说信息很简单：产品数据必须机器可读。',
