    quickAnswer: '2026 年 10 月 26 日，路透报道美国政治竞选正在用生成式引擎优化来影响 ChatGPT、Claude 和 Gemini 怎么描述候选人。奥斯汀的 Visigent 为 Mike Minogue 准备的一份提案，建议做几百个对 AI 友好的政策页、在高权重网站和 Reddit 上买位置，并追踪聊天机器人的回答直到体现候选人主张。政治业务起价每月 5,000 美元，最高每月 50,000 美元。Shopify 商家该抄的是信任机制，不是付费位置：挣第三方编辑提及、把产品页和政策页写成可引用的事实、按固定节奏在多个模型上追踪你的品牌。',
