    quickAnswer: '电商做 GEO 最关键的几种 schema：Product（含 name、brand、SKU、价格、库存）、AggregateRating（要和真实评价一致）、FAQPage（答案 40-60 词）、BreadcrumbList、以及首页的 Organization。用 Google 富媒体结果测试验证，确保 schema 和页面可见内容一致，并检查主题与插件是否各自插了一份互相打架的 schema。',
