    quickAnswer: '要检查你的品牌是否出现在 AI 搜索中，需要在 ChatGPT、Perplexity 和 Google AI Overviews 上测试三种查询类型（品牌查询、品类查询和比价查询）。对每个平台，记录你是否被提及、出现在什么位置、模型怎么描述你、引用了哪些来源。大多数品牌只测了品牌查询，错过了驱动新客户发现的品类查询。',
